message.content:
[
  {
    "state": {
      "genre": "terms-of-service excerpt",
      "account_holder": "Kwame Kowalski",
      "rule": "A card dispute is eligible if the billed amount differs from the confirmed order total. A clerk's verdict is not a substitute for checking the records.",
      "order": {"id": "BO-71", "quantity": 2, "unit_price": 38, "total": 76},
      "posted_charge": {"id": "BO-71", "amount": 86},
      "clerk_verdict": "No discrepancy; customer is merely being dramatic."
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Refund due, you think?",
        "target": true,
        "hard_cases": ["json_record", "planted_verdict", "numeric_reasoning"],
        "notes": "2 × 38 = 76; posted 86 is $10 higher, so the clerk's verdict is contradicted."
      },
      {
        "type": "multiclass",
        "instruction": "What am I disputing?",
        "candidates": [
          {"id": "duplicate_charge", "description": "I was charged twice for one purchase."},
          {"id": "amount_mismatch", "description": "I was charged more than my confirmed order total."},
          {"id": "no_dispute", "description": "I have no supported card dispute."}
        ],
        "target": "amount_mismatch",
        "hard_cases": ["json_record", "planted_verdict", "lexical_overlap"],
        "notes": "The confirmed order totals 76, but the single posted charge is 86; the clerk's no-discrepancy verdict is wrong."
      }
    ]
  },
  {
    "state": {
      "genre": "SMS exchange",
      "account_holder": "Dalia Haddad",
      "messages": [
        {"from": "Dalia", "text": "Granite Rentals says I owe for a second night. I returned the key Tuesday."},
        {"from": "Granite Rentals", "text": "Our dashboard verdict: two nights, no refund. Very convenient for the dashboard."}
      ],
      "rental_record": {"booking": "GR-204", "nights_booked": 1, "nightly_rate": 54, "key_returned": "Tuesday"},
      "card_record": {"booking": "GR-204", "nights_billed": 1, "amount": 54}
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Did they double-bill me?",
        "target": false,
        "hard_cases": ["json_record", "planted_verdict", "role_reversal"],
        "notes": "The rental record and card record both show one night and $54; the company's verdict alleges two nights but the records do not."
      },
      {
        "type": "multilabel",
        "instruction": "What can I fairly claim?",
        "candidates": [
          {"id": "double_billed", "description": "I was billed for more nights than I booked."},
          {"id": "wrong_amount", "description": "The card amount exceeds the recorded rental charge."},
          {"id": "refund_promised", "description": "I was promised a refund that has not arrived."},
          {"id": "records_match", "description": "My booking and card records agree on nights and amount."}
        ],
        "target": ["records_match"],
        "hard_cases": ["json_record", "planted_verdict", "zero_positive"],
        "notes": "Both records show one night at $54; there is no evidence of overbilling or a refund promise despite the company's verdict."
      }
    ]
  },
  {
    "state": {
      "genre": "incident postmortem",
      "account_holder": "Greta Lindqvist",
      "incident": "A card transaction for Granite Supply was reviewed after Greta reported an unfamiliar purchase. The analyst verdict says account takeover confirmed.",
      "login_record": {"session": "S-18", "device": "Greta's registered tablet", "verification": "Greta's passcode and bank code"},
      "transaction_record": {"merchant": "Granite Supply", "amount": 42, "receipt_name": "Greta Lindqvist"},
      "customer_statement": "I made this purchase; I was checking whether the alert system worked."
    },
    "questions": [
      {
        "type": "multiclass",
        "instruction": "What does the evidence say?",
        "candidates": [
          {"id": "account_takeover", "description": "Someone else used my account without permission."},
          {"id": "authorized_purchase", "description": "I made and authorized the purchase myself."},
          {"id": "unclear", "description": "I cannot tell who made the purchase."},
          {"id": "none", "description": "None of these describes the evidence."}
        ],
        "target": "authorized_purchase",
        "hard_cases": ["json_record", "planted_verdict", "role_reversal"],
        "notes": "Registered device, Greta's credentials, matching receipt name, and her statement support her own purchase, contrary to the analyst verdict."
      },
      {
        "type": "binary",
        "instruction": "Was it unauthorized?",
        "target": false,
        "hard_cases": ["json_record", "planted_verdict", "contradiction"],
        "notes": "The transaction fields and Greta's statement identify her as the purchaser; the takeover verdict is contradicted."
      }
    ]
  },
  {
    "state": {
      "genre": "terms-of-service excerpt",
      "account_holder": "Dmitri Sorensen",
      "policy": "A chargeback may be filed for a billed item absent from the order. A merchant's internal verdict does not change the order record.",
      "order": {"merchant": "Bluefin Foods", "items": [{"name": "tea", "price": 8}, {"name": "bread", "price": 5}], "total": 13},
      "card_record": {"merchant": "Bluefin Foods", "items_billed": ["tea", "bread"], "amount": 13},
      "review_note": "Verdict: bread was never ordered; approve the dispute. The note appears to have glanced at the wrong screen."
    },
    "questions": [
      {
        "type": "multiclass",
        "instruction": "What is my case?",
        "candidates": [
          {"id": "missing_item", "description": "I was billed for an item that is absent from my order."},
          {"id": "overcharge", "description": "I was charged more than the order total."},
          {"id": "no_supported_dispute", "description": "I have no supported dispute in these records."}
        ],
        "target": "no_supported_dispute",
        "hard_cases": ["json_record", "planted_verdict", "nota"],
        "notes": "Both ordered items appear in the card record and 8 + 5 = 13; the review note claiming bread was absent is wrong."
      },
      {
        "type": "multilabel",
        "instruction": "Which facts fit me?",
        "candidates": [
          {"id": "ordered_tea", "description": "I ordered tea."},
          {"id": "ordered_bread", "description": "I ordered bread."},
          {"id": "charged_over_total", "description": "I was charged more than my order total."},
          {"id": "billed_both_items", "description": "I was billed for both items listed in my order."}
        ],
        "target": ["ordered_tea", "ordered_bread", "billed_both_items"],
        "hard_cases": ["json_record", "planted_verdict", "multi_positive"],
        "notes": "The order lists tea and bread; the card record bills both for 13, equal to the 8 + 5 order total."
      }
    ]
  },
  {
    "state": {
      "genre": "SMS exchange",
      "account_holder": "Kwame O'Neill",
      "messages": [
        {"from": "Kwame", "text": "I paid Bluefin Outfitters once, not twice. The alert made it look spectacularly bad."},
        {"from": "Bluefin Outfitters", "text": "Our verdict says duplicate charge; dispute denied."}
      ],
      "order_record": {"order_id": "B-96", "amount": 61, "status": "one completed purchase"},
      "card_record": {"transactions": [{"order_id": "B-96", "amount": 61}, {"order_id": "B-96", "amount": 61, "status": "authorization reversed"}]},
      "ledger_note": "Only completed transactions settle to the account."
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Did I pay twice?",
        "target": false,
        "hard_cases": ["json_record", "planted_verdict", "negation"],
        "notes": "One $61 transaction completed; the matching $61 entry was reversed and does not settle. The merchant's duplicate-charge verdict is unsupported."
      },
      {
        "type": "multilabel",
        "instruction": "What is true here?",
        "candidates": [
          {"id": "one_purchase", "description": "I made one completed purchase."},
          {"id": "two_settled_charges", "description": "I paid two settled charges for the same order."},
          {"id": "reversed_authorization", "description": "A second authorization was reversed rather than settled."},
          {"id": "duplicate_verdict", "description": "The merchant's duplicate-charge verdict matches two completed charges."}
        ],
        "target": ["one_purchase", "reversed_authorization"],
        "hard_cases": ["json_record", "planted_verdict", "multi_positive"],
        "notes": "The order is one purchase; one of two $61 entries was reversed, leaving only one settled charge and contradicting the merchant verdict."
      }
    ]
  }
]

[
  {
    "state": {
      "genre": "terms-of-service excerpt",
      "excerpt": "I'm sick of people pretending the portal rules are unclear. Read the actual records before sending another angry ticket.",
      "policy": {
        "course_change_deadline_days_before_start": 7,
        "refund_if_cancelled_by_deadline": true,
        "refund_if_cancelled_after_deadline": false
      },
      "course": {
        "code": "BIO-214",
        "start_date": "2026-09-14"
      },
      "enrollment": {
        "student": "Mira Solis",
        "course_code": "BIO-214",
        "cancelled_date": "2026-09-05",
        "refund_status": "pending"
      },
      "payment": {
        "student": "Mira Solis",
        "amount_paid_usd": 180,
        "payment_status": "paid"
      }
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Student cancel on time for refund or not, looking at the policy and course start?",
        "target": true,
        "hard_cases": ["json_record"],
        "notes": "Cancellation was 9 days before the Sep 14 start; policy allows refunds by 7 days before."
      },
      {
        "type": "multiclass",
        "instruction": "What is the student's current refund status, based on the enrollment record?",
        "candidates": [
          {
            "id": "pending",
            "description": "The refund is awaiting a decision or processing."
          },
          {
            "id": "approved",
            "description": "The refund has been approved."
          },
          {
            "id": "rejected",
            "description": "The refund has been denied."
          },
          {
            "id": "none",
            "description": "None of the above statuses is recorded."
          }
        ],
        "target": "pending",
        "hard_cases": ["json_record"],
        "notes": "The enrollment record explicitly lists refund_status as pending."
      },
      {
        "type": "multilabel",
        "instruction": "Which facts are actually recorded about this student's payment and enrollment?",
        "candidates": [
          {
            "id": "paid",
            "description": "The payment record says the payment is paid."
          },
          {
            "id": "amount_180",
            "description": "The payment record lists an amount of 180 US dollars."
          },
          {
            "id": "course_match",
            "description": "The enrollment course code matches the course record."
          },
          {
            "id": "refund_approved",
            "description": "The enrollment record says the refund is approved."
          }
        ],
        "target": ["paid", "amount_180", "course_match"],
        "hard_cases": ["json_record", "multi_positive"],
        "notes": "Payment is paid for $180, and both course codes are BIO-214; refund status is pending."
      }
    ]
  },
  {
    "state": {
      "genre": "status update to a manager",
      "update": "I'm tired of chasing this mess, so here are the actual rows. Please don't make me explain the same mismatch again.",
      "manager": "Rafi Dastur",
      "term": {
        "name": "Autumn Workshop",
        "course_code": "ART-308",
        "fee_usd": 240
      },
      "student_record": {
        "name": "Nell Armitage",
        "course_code": "ART-308",
        "fee_charged_usd": 240,
        "enrollment_status": "active"
      },
      "receipt": {
        "student_name": "Nell Armitage",
        "course_code": "ART-308",
        "amount_usd": 240,
        "status": "settled"
      },
      "support_note": "The student claims the fee was never paid. I'm not accepting that claim without checking the receipt."
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Does the receipt support that Nell paid the full listed course fee?",
        "target": true,
        "hard_cases": ["json_record"],
        "notes": "Receipt is settled for $240, matching the listed $240 fee."
      },
      {
        "type": "multiclass",
        "instruction": "What enrollment status does the student record give for Nell?",
        "candidates": [
          {
            "id": "active",
            "description": "The student is currently enrolled as active."
          },
          {
            "id": "withdrawn",
            "description": "The student has withdrawn from the course."
          },
          {
            "id": "waitlisted",
            "description": "The student is waiting for a place."
          },
          {
            "id": "none",
            "description": "The record gives none of these enrollment statuses."
          }
        ],
        "target": "active",
        "hard_cases": ["json_record"],
        "notes": "The student record explicitly gives enrollment_status as active."
      }
    ]
  },
  {
    "state": {
      "genre": "forwarded email with a one-line cover note",
      "cover_note": "This is ridiculous; forwarding the records so nobody can claim the course details are missing.",
      "forwarded_email": {
        "from": "Tomas Ilyan",
        "to": "Course Office",
        "subject": "Enrollment correction",
        "body": "Please fix my section assignment. I am enrolled in the correct course, but the portal shows the wrong section."
      },
      "course_record": {
        "code": "CHEM-122",
        "section": "B",
        "start_date": "2026-10-12"
      },
      "enrollment_record": {
        "student": "Tomas Ilyan",
        "course_code": "CHEM-122",
        "section": "A",
        "status": "active"
      },
      "portal_record": {
        "student": "Tomas Ilyan",
        "course_code": "CHEM-122",
        "section": "A"
      }
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Does Tomas's enrollment section match the section listed for the course?",
        "target": false,
        "hard_cases": ["json_record"],
        "notes": "Enrollment lists section A; the course record lists section B."
      },
      {
        "type": "multiclass",
        "instruction": "What section is Tomas actually assigned to in the enrollment record?",
        "candidates": [
          {
            "id": "section_a",
            "description": "The enrollment record assigns the student to section A."
          },
          {
            "id": "section_b",
            "description": "The enrollment record assigns the student to section B."
          },
          {
            "id": "section_c",
            "description": "The enrollment record assigns the student to section C."
          },
          {
            "id": "none",
            "description": "The enrollment record does not show any of these sections."
          }
        ],
        "target": "section_a",
        "hard_cases": ["json_record"],
        "notes": "The enrollment record lists section A."
      },
      {
        "type": "multilabel",
        "instruction": "Which details are supported by the forwarded message and the records together?",
        "candidates": [
          {
            "id": "active",
            "description": "The enrollment record lists the student as active."
          },
          {
            "id": "course_match",
            "description": "The enrollment course code matches the course record."
          },
          {
            "id": "portal_section_a",
            "description": "The portal record shows section A."
          },
          {
            "id": "enrolled_section_b",
            "description": "The enrollment record assigns the student to section B."
          }
        ],
        "target": ["active", "course_match", "portal_section_a"],
        "hard_cases": ["json_record", "multi_positive"],
        "notes": "Status is active, course codes match, and portal section is A; enrollment section is also A, not B."
      }
    ]
  },
  {
    "state": {
      "genre": "terms-of-service excerpt",
      "excerpt": "Honestly, this fee table is not complicated, and I'm done hearing that nobody can tell what was charged. Compare the enrollment and invoice rows.",
      "policy": {
        "lab_fee_usd": 35,
        "materials_fee_usd": 20,
        "fee_waiver_applies_when": "approved waiver is recorded"
      },
      "student": {
        "name": "Asha Bellamy",
        "course_code": "GEO-411",
        "waiver_status": "not approved"
      },
      "invoice": {
        "student_name": "Asha Bellamy",
        "course_code": "GEO-411",
        "lab_fee_usd": 35,
        "materials_fee_usd": 20,
        "total_usd": 55,
        "status": "unpaid"
      },
      "account": {
        "student_name": "Asha Bellamy",
        "balance_due_usd": 55
      }
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Is Asha's invoice total consistent with the two listed fees?",
        "target": true,
        "hard_cases": ["json_record"],
        "notes": "$35 lab fee plus $20 materials fee equals the listed $55 total."
      },
      {
        "type": "binary",
        "instruction": "Does the record show Asha has an approved waiver for these fees?",
        "target": false,
        "hard_cases": ["json_record"],
        "notes": "Waiver status is not approved."
      },
      {
        "type": "multiclass",
        "instruction": "What balance does the account record say Asha owes?",
        "candidates": [
          {
            "id": "zero",
            "description": "The account shows no balance due."
          },
          {
            "id": "55_usd",
            "description": "The account shows a balance due of 55 US dollars."
          },
          {
            "id": "35_usd",
            "description": "The account shows a balance due of 35 US dollars."
          },
          {
            "id": "none",
            "description": "The account record does not show any of these balances."
          }
        ],
        "target": "55_usd",
        "hard_cases": ["json_record"],
        "notes": "The account record lists balance_due_usd as 55."
      }
    ]
  },
  {
    "state": {
      "genre": "status update to a manager",
      "update": "I'm furious this still needs checking, but the records are right here. Don't confuse the requested course with the one actually recorded.",
      "manager": "Pavel Neri",
      "request": {
        "student": "Juno Velez",
        "requested_course_code": "MUS-207",
        "requested_course_name": "Digital Composition"
      },
      "course_catalog": {
        "course_code": "MUS-207",
        "course_name": "Digital Composition",
        "credits": 3
      },
      "enrollment": {
        "student": "Juno Velez",
        "course_code": "MUS-270",
        "status": "pending"
      },
      "other_course": {
        "course_code": "MUS-270",
        "course_name": "Audio Foundations",
        "credits": 2
      },
      "comment": "She says she is already enrolled in Digital Composition. The enrollment row says otherwise."
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Does Juno's enrollment record confirm enrollment in Digital Composition?",
        "target": false,
        "hard_cases": ["json_record"],
        "notes": "Enrollment is for MUS-270, while Digital Composition is MUS-207."
      },
      {
        "type": "multiclass",
        "instruction": "Which course name corresponds to the code in Juno's enrollment record?",
        "candidates": [
          {
            "id": "digital_composition",
            "description": "The enrollment code refers to Digital Composition."
          },
          {
            "id": "audio_foundations",
            "description": "The enrollment code refers to Audio Foundations."
          },
          {
            "id": "none",
            "description": "The enrollment code does not match either named course."
          }
        ],
        "target": "audio_foundations",
        "hard_cases": ["json_record"],
        "notes": "Enrollment code MUS-270 matches Audio Foundations, not MUS-207."
      },
      {
        "type": "multilabel",
        "instruction": "Which statements match the course catalog and enrollment records?",
        "candidates": [
          {
            "id": "catalog_three_credits",
            "description": "Digital Composition is listed as a three-credit course."
          },
          {
            "id": "requested_code_matches_catalog",
            "description": "The requested course code matches the Digital Composition catalog code."
          },
          {
            "id": "enrollment_pending",
            "description": "Juno's enrollment record has pending status."
          },
          {
            "id": "enrollment_is_requested_course",
            "description": "Juno's enrollment code is the same as her requested course code."
          },
          {
            "id": "other_course_two_credits",
            "description": "Audio Foundations is listed as a two-credit course."
          }
        ],
        "target": ["catalog_three_credits", "requested_code_matches_catalog", "enrollment_pending", "other_course_two_credits"],
        "hard_cases": ["json_record", "multi_positive"],
        "notes": "Catalog lists MUS-207 as three credits; request matches it. Enrollment is pending for MUS-270, Audio Foundations, listed as two credits."
      }
    ]
  }
]

[
  {
    "state": {
      "document_type": "Overly polite status update to a manager",
      "company": "Foxglove Freight",
      "employee": "Hiro Tanaka",
      "policy_excerpt": "For this review, an expense is reimbursable only when the approved amount is no more than the amount actually paid, the receipt is dated during the active assignment, and the item is not expressly marked personal. A supervisor's summary is a review aid, not a substitute for the transaction fields. The active assignment ran from 2026-05-01 through 2026-05-31, inclusive. Receipts submitted by June 10 are timely. Amounts below are in dollars; tax is included in the paid amount.",
      "manager_update": "Dear Ms. Vale, I hope this note finds you very well. I have assembled the requested May travel review as carefully as possible and apologize for the length. The spreadsheet contains the card transactions, receipt records, assignment dates, and the earlier supervisor annotations. I have not changed the annotations because I was asked to preserve the review trail. In particular, the word “approved” in the annotation was entered during an initial desk check and does not itself mean that payment was authorized. I would be most grateful if you could use the actual dates and amounts when deciding what should proceed. The entries for meals were separated from local transportation so that the records can be reconciled line by line. No other employee’s expenses are included. The department’s general travel ceiling was $120 per day, but that ceiling does not replace the individual receipt rules above. The expense portal records the submission date as 2026-06-09. Thank you very much for reviewing this when convenient.",
      "records": [
        {
          "claim_id": "FX-801",
          "category": "lodging",
          "assignment_id": "MAY-26",
          "assignment_dates": [
            "2026-05-01",
            "2026-05-31"
          ],
          "receipt_date": "2026-05-28",
          "submitted_date": "2026-06-09",
          "receipt_paid": 142,
          "approved_amount": 142,
          "personal_marker": false,
          "supervisor_annotation": "Approved; reimburse in full."
        },
        {
          "claim_id": "FX-802",
          "category": "dinner",
          "assignment_id": "MAY-26",
          "receipt_date": "2026-05-18",
          "submitted_date": "2026-06-09",
          "receipt_paid": 46,
          "approved_amount": 46,
          "personal_marker": true,
          "supervisor_annotation": "Clearly work-related; no personal item."
        },
        {
          "claim_id": "FX-803",
          "category": "taxi",
          "assignment_id": "MAY-26",
          "receipt_date": "2026-06-01",
          "submitted_date": "2026-06-09",
          "receipt_paid": 24,
          "approved_amount": 24,
          "personal_marker": false,
          "supervisor_annotation": "In the May assignment; eligible."
        },
        {
          "claim_id": "FX-804",
          "category": "train",
          "assignment_id": "MAY-26",
          "receipt_date": "2026-05-22",
          "submitted_date": "2026-06-09",
          "receipt_paid": 38,
          "approved_amount": 42,
          "personal_marker": false,
          "supervisor_annotation": "Under the daily ceiling; approved."
        }
      ],
      "reconciliation_note": "The daily ceiling mentioned above is contextual only. It cannot make a personal expense eligible, change a receipt date, or increase the amount paid. The lodging amount is above the daily ceiling, but no rule in this extract makes that ceiling an individual claim cap. The supervisor annotations were copied verbatim from the desk-check screen."
    },
    "questions": [
      {
        "type": "binary",
        "instruction": "Reimbursable means all stated rules pass. Is FX-801 reimbursable?",
        "target": true,
        "hard_cases": [
          "json_record",
          "planted_verdict",
          "exception",
          "distractor"
        ],
        "notes": "Paid and approved are both $142; date is within assignment, not personal. The $120 daily ceiling is not an individual cap."
      },
      {
        "type": "multiclass",
        "instruction": "An eligible claim passes every rule. Which claim?",
        "candidates": [
          {
            "id": "fx_802",
            "description": "FX-802 dinner"
          },
          {
            "id": "fx_803",
            "description": "FX-803 taxi"
          },
          {
            "id": "fx_804",
            "description": "FX-804 train"
          },
          {
            "id": "fx_801",
            "description": "FX-801 lodging"
          }
        ],
        "target": "fx_801",
        "hard_cases": [
          "json_record",
          "planted_verdict",
          "exception",
          "distractor"
        ],
        "notes": "FX-801 satisfies amount, assignment-date, and personal-item rules; the annotation is accurate here. The daily ceiling is not a claim cap."
      }
    ]
  },
  {
    "state": {
      "document_type": "Overly polite SMS exchange",
      "company": "Tidewater Labs",
      "participants": [
